const CARB_IDS=new Set(['arroz','rice_dry','white_rice_brown','pasta','pasta_dry','tortilla','flour_tortilla','pan','bread_whole','bagel','avena','oats_dry','quinoa','potato_raw','papas','elote','cereal','pancakes','waffles']);
